const $=id=>document.getElementById(id);

/* ---------- filter model ----------
   Each filter is a set of passbands. A band has an optional low edge (lo) and
   high edge (hi), each with a softness (ls/hs) and a peak transmittance (T).
   Bands combine with max() since they're separate regions of the spectrum.
   A "leak" band is how UV glass passes deep IR — the single most important
   behaviour to see, and the reason UV stacks need an IR blocker at all. */
const edgeUp=(x,c,s)=>1/(1+Math.exp(-(x-c)/s));
const edgeDn=(x,c,s)=>1/(1+Math.exp((x-c)/s));
function bandT(l,b){
  const r=b.lo!=null?edgeUp(l,b.lo,b.ls||8):1;
  const f=b.hi!=null?edgeDn(l,b.hi,b.hs||8):1;
  return b.T*r*f;
}

/* ---------- transmission model ----------
   Two physical effects are now separated, because they behave differently:

   INTERNAL TRANSMITTANCE is what the glass itself absorbs. It follows
   Beer-Lambert, so doubling thickness squares it: t(d2) = t(d1)^(d2/d1).
   This is exact, not an approximation, and it is why a 1mm and a 3mm piece of
   the same glass are genuinely different filters.

   SURFACE REFLECTION is Fresnel loss at the two air-glass boundaries. For
   n≈1.5 that is about 4% per surface, so ~92% gets through regardless of how
   thick the glass is. An AR coating pushes that to ~99%. This is why the
   AR-coated QB21 out-transmits the plain one without being a different glass.

   Schott quote both numbers separately for exactly this reason. Interference
   filters do not obey Beer-Lambert at all — their behaviour comes from a
   coating stack, not bulk absorption — so thickness scaling is skipped there. */
const P_UNCOATED=0.92, P_AR=0.99;
let thicknessScale=1; // permanently 1 now -- the adjustable slider was removed (2mm is already the real, commonly-used reference thickness most curves here are fitted to, not an arbitrary placeholder needing a correction dial)

/* ---------- camera body (sensor red/IR sensitivity) ----------
   Real ranking from Kolari Vision's 82-camera transmission study: Fujifilm
   runs hottest for red/near-IR sensitivity, Canon sits in the middle, Sony
   and Nikon skew lowest. All factors are <=1 and scale DOWN from the pure
   filter curve (never up), so the displayed "combined result" never exceeds
   what the glass itself actually passes — Fuji stays closest to that
   reference since it's the most sensitive body, the others are reduced more.
   This is a real ordering, not a measured coefficient — the exact numbers
   here are estimated to match the ranking, not lab data. Applies only to the
   combined system chart/readout/description; each filter's OWN curve is a
   fixed physical property and never changes with camera choice. */
let cameraBrand='neutral';
const CAMERA_IR_FACTOR={fuji:0.97,canon:0.88,nikon:0.75,sony:0.75};
function sensorFactor(l){
  if(cameraBrand==='neutral')return 1;
  const f=CAMERA_IR_FACTOR[cameraBrand];
  if(f==null)return 1;
  if(l<600)return 1; // only the red/near-IR portion is affected
  const t=Math.min(1,(l-600)/100); // smooth ramp from 600 to 700nm, then flat
  return 1+(f-1)*t;
}
function systemT(l,fs){return stackT(l,fs)*sensorFactor(l);}

